import java.util.*;
import java.io.*;

public class Main {
    static int[] distances(int n, int[][] edges, int s, int c) {
        // Return, for every node, the fewest links from s (corrupted node c cannot be passed through), or -1
        // Write your solution here
        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        return dist;
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        in.nextToken();
        int s = (int) in.nval;
        in.nextToken();
        int c = (int) in.nval;
        int[][] edges = new int[m][2];
        for (int i = 0; i < m; i++) {
            in.nextToken();
            edges[i][0] = (int) in.nval;
            in.nextToken();
            edges[i][1] = (int) in.nval;
        }
        int[] dist = distances(n, edges, s, c);
        StringBuilder a = new StringBuilder(), b = new StringBuilder();
        for (int i = 0; i < n; i++) {
            a.append(dist[i] >= 0 ? 1 : 0).append(i + 1 < n ? " " : "\n");
            b.append(dist[i]).append(i + 1 < n ? " " : "\n");
        }
        System.out.print(a);
        System.out.print(b);
    }
}
